$resultMessage = $this->saveUser();
                    if ($resultMessage === "OK") {
                        // FERTIG, Nutzer angelegt/bearbeitet, zurück zur Übersichtsseite
                        Page::redirectParentPage();
                    } else {
                        $this->addHtmlMessage($resultMessage);
                    }
                } else {
                    $this->addHtmlMessage('Bitte korrigieren Sie Ihre Eingaben!');
                }
                $this->addMainModule($form);
            } elseif ($ldapAddMode !== '') {
                $ldapUserName = Tools::prepareFormString($_POST, 'ldap_user');

                $message = LdapUser::addLdapUser(
                    $ldapUserName,
                    $this->dienstStelle,
                    $this->getAccessLevel()
                );

                if ($message === "OK") {
                    Page::redirectLocal(Navigation::getParentPageLink());
                }

                $this->addHtmlMessage($message);
                $this->addLdapForm();
            } elseif ($cancelMode !== '') {
                /* Abbrechen-Modus */
                Page::redirectLocal(Navigation::getParentPageLink());
            } elseif ($ldapSearch !== '') {
                $searchString = Tools::prepareFormString($_POST, 'search_string');

                if (!empty($searchString)) {
                    $ldapUtility = LdapUtility::getInstance();
                    if (!$ldapUtility->connect()) {
                        var_dump($ldapUtility->getStatus());
                        exit("LDAP-Connection Error");
                    }

                    if (!$ldapUtility->bind()) {
                        var_dump($ldapUtility->getStatus());
                        exit("LDAP-Bind Error");
                    }

                    if (!$ldapUtility->search(null, '(mail=*)')) {
                        var_dump($ldapUtility->getStatus());
                        exit("LDAP-Search Error");
                    }
                    $results = $ldapUtility->getEntries();
                    $cleanResults = [];
                    if (!empty($results) && $results['count'] > 0) {
                        foreach (\array_slice($results, 1) as $entry) {
                            $key   = $entry['cn'][0];
                            $value = $entry['mail'][0];
                            $cleanResults[$key] = $value;
                        }
                    }
                    $this->ldapSearchResults = $cleanResults;

                    $ldapUtility->disconnect();
                }

                $this->addLdapForm();
            }
        } else {
            // Formularfelder-Definition generieren

            $this->addMainModule(new SimpleTemplate('RequireDescription.tpl'));

            // LDAP-Form nur im neuen-Nutzer-Modus verfügbar
            if (!$this->saved) {
                $this->addLdapForm();
            }

            $this->buildFormFieldsGetMode();
            $form = new DynForm(
                $this->formFields,
                $this->buttons,
                'Lokales Nutzerkonto ' . ($this->saved ? 'bearbeiten' : 'anlegen'),
                'local-user-' . ($this->saved ? 'edit' : 'add')
            );
